// A Nuvio "stream badge" pack (Fusion-style JSON).
//
// Nuvio draws a chip for every imported rule whose regular expression matches a
// stream's name, title or description and that has an `imageURL`. Rules are
// imported by URL in Nuvio's stream badge settings (up to three URLs). The
// patterns below match both the tokens the default AIOPlugins formatter prints
// and the usual release-name spellings. Nuvio compiles them with
// java.util.regex and no default flags, so each starts with `(?i)`.
//
// Images live in public/badges and are generated by scripts/generate-badges.py
// from the same ids; a test keeps the two in sync.

export interface BadgeDefinition {
  id: string;
  label: string;
  group: string;
  pattern: string;
}

export const BADGE_GROUPS = [
  { id: "resolution", name: "Resolution", color: "#7C3AED" },
  { id: "hdr", name: "HDR", color: "#EA580C" },
  { id: "audio", name: "Audio", color: "#16A34A" },
  { id: "source", name: "Source", color: "#2563EB" },
  { id: "codec", name: "Codec", color: "#0D9488" },
  { id: "extra", name: "Extras", color: "#DB2777" }
] as const;

export const BADGE_DEFINITIONS: BadgeDefinition[] = [
  { id: "res-4k", label: "4K", group: "resolution", pattern: String.raw`(?i)\b(?:2160p?|4k|uhd)\b` },
  { id: "res-1440p", label: "1440p", group: "resolution", pattern: String.raw`(?i)\b(?:1440p|qhd)\b` },
  { id: "res-1080p", label: "1080p", group: "resolution", pattern: String.raw`(?i)\b(?:1080p|fhd)\b` },
  { id: "res-720p", label: "720p", group: "resolution", pattern: String.raw`(?i)\b(?:720p|hd)\b` },
  { id: "res-sd", label: "SD", group: "resolution", pattern: String.raw`(?i)\b(?:576p|480p|360p|240p|144p|sd)\b` },

  { id: "hdr-dv", label: "Dolby Vision", group: "hdr", pattern: String.raw`(?i)\b(?:dolby[ ._-]?vision|dovi|dv)\b` },
  { id: "hdr-hdr10plus", label: "HDR10+", group: "hdr", pattern: String.raw`(?i)\bhdr10(?:\+|plus)` },
  { id: "hdr-hdr10", label: "HDR10", group: "hdr", pattern: String.raw`(?i)\bhdr10(?![+\w])` },
  { id: "hdr-hdr", label: "HDR", group: "hdr", pattern: String.raw`(?i)\bhdr\b` },
  { id: "hdr-10bit", label: "10-bit", group: "hdr", pattern: String.raw`(?i)\b10[ -]?bit\b` },

  { id: "audio-atmos", label: "Atmos", group: "audio", pattern: String.raw`(?i)\batmos\b` },
  { id: "audio-truehd", label: "TrueHD", group: "audio", pattern: String.raw`(?i)\btrue[ ._-]?hd\b` },
  { id: "audio-dtsx", label: "DTS:X", group: "audio", pattern: String.raw`(?i)\bdts[ ._:-]?x\b` },
  { id: "audio-dtshd", label: "DTS-HD", group: "audio", pattern: String.raw`(?i)\bdts[ ._-]?hd(?:[ ._-]?ma)?\b` },
  { id: "audio-dts", label: "DTS", group: "audio", pattern: String.raw`(?i)\bdts\b(?![ ._:-]?(?:hd|x)\b)` },
  { id: "audio-ddp", label: "DD+", group: "audio", pattern: String.raw`(?i)(?:\bdd\+|\bddp|\be-?ac-?3\b)` },
  { id: "audio-dd", label: "DD", group: "audio", pattern: String.raw`(?i)\b(?:dd(?![+\w])|dd(?=\d)|ac-?3)` },
  { id: "audio-aac", label: "AAC", group: "audio", pattern: String.raw`(?i)\baac\b` },
  { id: "audio-flac", label: "FLAC", group: "audio", pattern: String.raw`(?i)\bflac\b` },
  { id: "audio-opus", label: "Opus", group: "audio", pattern: String.raw`(?i)\bopus\b` },
  { id: "audio-71", label: "7.1", group: "audio", pattern: String.raw`\b7\.1\b` },
  { id: "audio-51", label: "5.1", group: "audio", pattern: String.raw`\b5\.1\b` },

  { id: "src-remux", label: "REMUX", group: "source", pattern: String.raw`(?i)\bremux\b` },
  { id: "src-bluray", label: "BluRay", group: "source", pattern: String.raw`(?i)\b(?:blu[ ._-]?ray|bdrip|brrip)\b` },
  { id: "src-webdl", label: "WEB-DL", group: "source", pattern: String.raw`(?i)\bweb[ ._-]?dl\b` },
  { id: "src-webrip", label: "WEBRip", group: "source", pattern: String.raw`(?i)\bweb[ ._-]?rip\b` },
  { id: "src-hdtv", label: "HDTV", group: "source", pattern: String.raw`(?i)\bhdtv\b` },
  { id: "src-dvd", label: "DVD", group: "source", pattern: String.raw`(?i)\bdvd(?:[ ._-]?rip)?\b` },
  { id: "src-cam", label: "CAM", group: "source", pattern: String.raw`(?i)\b(?:cam(?:rip)?|hd-?cam|telesync|hd-?ts)\b` },

  { id: "codec-hevc", label: "HEVC", group: "codec", pattern: String.raw`(?i)\b(?:hevc|x265|h[ .-]?265)\b` },
  { id: "codec-avc", label: "AVC", group: "codec", pattern: String.raw`(?i)\b(?:avc|x264|h[ .-]?264)\b` },
  { id: "codec-av1", label: "AV1", group: "codec", pattern: String.raw`(?i)\bav1\b` },

  { id: "extra-imax", label: "IMAX", group: "extra", pattern: String.raw`(?i)\bimax\b` },
  { id: "extra-3d", label: "3D", group: "extra", pattern: String.raw`(?i)\b3d\b` },
  { id: "extra-dual", label: "Dual Audio", group: "extra", pattern: String.raw`(?i)\bdual[ ._-]?audio\b` },
  { id: "extra-multi", label: "Multi", group: "extra", pattern: String.raw`(?i)\bmulti(?:[ ._-]?(?:audio|lang\w*))?\b` }
];

export function buildBadgePack(origin: string, appVersion: string) {
  return {
    name: "AIOPlugins stream badges",
    version: appVersion,
    groups: BADGE_GROUPS.map(group => ({ ...group, isExpanded: true })),
    filters: BADGE_DEFINITIONS.map(badge => ({
      id: badge.id,
      groupId: badge.group,
      name: badge.label,
      pattern: badge.pattern,
      imageURL: new URL(`/badges/${badge.id}.png`, origin).toString(),
      isEnabled: true,
      tagColor: "",
      tagStyle: "",
      textColor: "",
      borderColor: ""
    }))
  };
}
